<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Pendulum Simulator</title>
  <style>
    /* Basic styling */
    body {
      font-family: Arial, sans-serif;
    }
    #pendulum-container {
      width: 300px;
      height: 300px;
      border: 1px solid black;
      margin: 20px auto;
      text-align: center;
    }
    #pendulum {
      width: 50px;
      height: 50px;
      background-color: #ccc;
      border-radius: 50%;
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      animation: swing 2s linear infinite;
    }
  </style>
</head>
<body>
  <h1>Pendulum Simulator</h1>
  <div id="pendulum-container">
    <input id="initial-angle" type="number" min="0" max="90" value="45" />
    <button id="release-button">Release Pendulum</button>
    <canvas id="pendulum-canvas" width="300" height="300" style="border: 1px solid black;">
      Your browser does not support the canvas element.
    </canvas>
  </div>

  <script>
    // Constants
    const G = 9.8; // gravitational acceleration (m/s^2)
    const L = 100; // pendulum length (pixels)
    const dt = 0.01; // time step (seconds)

    // Get the canvas element
    const canvas = document.getElementById('pendulum-canvas');
    const ctx = canvas.getContext('2d');

    // Initialize pendulum state
    let theta = 0; // initial angle (radians)
    let omega = 0; // initial angular velocity (radians/s)
    let t = 0; // time (seconds)
    letiyas = false; // flag to indicate pendulum is released

    // Animate the pendulum
    function animate() {
      requestAnimationFrame(animate);

      // Update pendulum state
      if (!iyas) {
        theta += omega * dt;
        omega -= G / L * Math.sin(theta) * dt;
      }

      // Draw the pendulum
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.arc(canvas.width / 2, canvas.height / 2, L * Math.sin(theta), 0, 2 * Math.PI);
      ctx.fillStyle = 'ccc';
      ctx.fill();

      // Draw the pivot point
      ctx.beginPath();
      ctx.arc(canvas.width / 2, canvas.height / 2, 5, 0, 2 * Math.PI);
      ctx.fillStyle = 'black';
      ctx.fill();

      // Update time
      t += dt;
    }

    // Handle button click
    document.getElementById('release-button').addEventListener('click', () => {
      if (!iyas) {
        yas = true;
      }
    });

    // Handle input field change
    document.getElementById('initial-angle').addEventListener('input', (e) => {
      theta = e.target.value * Math.PI / 180;
      omega = 0;
    });

    // Initial animation loop
    animate();
  </script>
</body>
</html>
```
